class Solution:
    def mergeTwoLists(self, list1, list2):
        dummy = ListNode()
        tail = dummy
        while list1 and list2:
            if list1.val <= list2.val:
                tail.next = list1
                list1 = list1.next
            else:
                tail.next = list2
                list2 = list2.next
            tail = tail.next
        tail.next = list1 if list1 else list2
        return dummy.next

class Solution:
    def smallestStableIndex(self, nums):
        n = len(nums)
        total = sum(nums)
        best = -1
        for i in range(n):
            if max(nums[i:]) <= total - nums[i]:
                if best == -1:
                    best = i
        return best

class Solution:
    def constructUniformParityArray(self, nums):
        candidate = -1
        for x in nums:
            if x % 2 == 1:
                candidate = x
                break
        if candidate == -1:
            return []
        for i in range(len(nums)):
            if nums[i] % 2 == 0:
                nums[i] = candidate
        return nums

class Solution:
    def constructUniformParityArray(self, nums):
        candidate = -1
        for x in nums:
            if x % 2 == 1 and x > candidate:
                candidate = x
        for i in range(len(nums)):
            if nums[i] % 2 == 0:
                nums[i] = candidate
        return nums

class Solution:
    def moveZeroes(self, nums):
        left = 0
        for right in range(len(nums)):
            if nums[right] != 0:
                nums[left], nums[right] = nums[right], nums[left]
                left += 1

class Solution:
    def pivotIndex(self, nums):
        total = sum(nums)
        left = 0
        for i, x in enumerate(nums):
            if left == total - left - x:
                return i
            left += x
        return -1
